const LEADIN = ["hi", "hello", "hey", "my", "name", "is", "am", "i", "im", "i'm", "it's", "its", "this", "call", "me", "you", "can", "please", "the"];
const STOP = ["what", "how", "much", "cost", "price", "prices", "treatment", "cancer", "lung", "breast", "prostate", "pancreatic", "colon", "colorectal", "package", "packages", "does", "do", "could", "would", "will", "are", "where", "when", "why", "who", "yes", "no", "ok", "okay", "thanks", "thank", "help", "quote", "itc", "tijuana", "mexico", "include", "included", "pricing", "inpatient", "outpatient", "adenocarcinoma", "adrenal", "anal", "stage", "tell", "about", "need", "want", "know", "book", "appointment", "recovery", "time", "safe", "and", "for", "with"];
